package com.commercecore.order;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import jakarta.validation.constraints.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;import java.util.UUID;@RestController@RequestMapping("/api/v1/orders")@SecurityRequirement(name="bearerAuth")public class CustomerOrderController{private final OrderService orders;public CustomerOrderController(OrderService o){orders=o;}@GetMapping OrderDtos.PageResponse<OrderDtos.OrderResponse>list(@AuthenticationPrincipal Jwt jwt,@RequestParam(defaultValue="0")@Min(0)int page,@RequestParam(defaultValue="20")@Min(1)@Max(100)int size){return orders.customerOrders(user(jwt),page,size);}@GetMapping("/{id}")OrderDtos.OrderResponse get(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID id){return orders.customerOrder(user(jwt),id);}@PostMapping("/{id}/cancel")OrderDtos.OrderResponse cancel(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID id){return orders.cancelCustomer(user(jwt),id);}@GetMapping("/{id}/tracking")OrderDtos.ShipmentResponse tracking(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID id){return orders.customerTracking(user(jwt),id);}private static UUID user(Jwt jwt){return UUID.fromString(jwt.getSubject());}}
